let pad=null;
function zwTerug(){
  try{
    const L=S.login||{};
    if(!L.laatst)return false;
    const v=typeof vandaag==='function'?vandaag():'';
    return !!(v&&L.laatst!==v);
  }catch(e){return false}
}
function padStop(){try{if(pad){clearTimeout(pad.timer);const t=pad.ac.currentTime;pad.g.gain.cancelScheduledValues(t);pad.g.gain.setValueAtTime(pad.g.gain.value,t);pad.g.gain.linearRampToValueAtTime(0,t+.4);const p=pad;setTimeout(()=>{try{(p.os||[]).forEach(o=>{try{o.stop()}catch(e){}});}catch(e){}try{p.ns&&p.ns.stop()}catch(e){}if(pad===p)pad=null},500)}}catch(e){pad=null}}
function padStart(){
  try{
    if(RMX||S.muziekAan===false||S.geluid===false||S.stil)return padStop();
    if(window._zwPak)return padStop();
    if(document.hidden||document.body.dataset.view==='match3')return padStop();
    if(pad)return;
    const ac=(window.fx&&fx.ctx&&(fx.ctx().ac))||new (window.AudioContext||window.webkitAudioContext)();
    if(ac.state==='suspended')ac.resume();
    const master=ac.createGain();master.gain.value=0;master.connect(ac.destination);
    const vol=.08*(S.muziekVol==null?.5:S.muziekVol);
    /* Eigen compositie "Lantaarn in de Hal": 3/4, F-majeur, celesta + zacht akkoord.
       Geen bestaande melodie, geen film- of spellied. */
    const N=m=>440*Math.pow(2,(m-69)/12);
    const BEAT=.42;
    const winter=document.body.classList.contains('winter');
    const tr=winter?3:0;
    const MEL=[[65,0,1],[69,1,1],[72,2,1],[74,3,1],[72,4,1],[69,5,1],[70,6,1],[69,7,1],[67,8,1],[69,9,2],[65,11,1],[67,12,1],[69,13,1],[72,14,1],[70,15,1.5],[69,16.5,.5],[67,17,1],[65,18,1],[69,19,1],[67,20,1],[65,21,3]];
    const AKK=[[[53,57,60],0,6],[[50,53,57],6,6],[[48,52,55],12,6],[[53,57,60],18,6]];
    const os=[];
    const stem=(hz,t,d,g,type)=>{
      const o=ac.createOscillator(),gg=ac.createGain(),ff=ac.createBiquadFilter();
      o.type=type||'sine';o.frequency.value=hz;ff.type='lowpass';ff.frequency.value=type==='triangle'?2200:1800;
      gg.gain.setValueAtTime(0,t);gg.gain.linearRampToValueAtTime(g,t+.04);gg.gain.exponentialRampToValueAtTime(.0008,t+d);
      o.connect(ff);ff.connect(gg);gg.connect(master);o.start(t);o.stop(t+d+.05);os.push(o);
    };
    const cel=(hz,t,d,g)=>{stem(hz,t,d*1.15,g,'sine');stem(hz*2.005,t,d*.55,g*.28,'triangle');};
    const sched=()=>{
      if(!pad||pad.ac!==ac)return;
      os.length=0;
      const now=ac.currentTime+0.08;
      AKK.forEach(([chs,b,dd])=>{const t=now+b*BEAT,len=dd*BEAT;
        chs.forEach((m,i)=>stem(N(m+tr-12),t+i*.03,len*1.05,.028,'triangle'));
      });
      MEL.forEach(([m,b,dd])=>{
        const t=now+b*BEAT;cel(N(m+tr),t,dd*BEAT,.07);
        if(winter)stem(N(m+tr+12),t+.02,dd*BEAT*.7,.016,'sine');
      });
      pad.timer=setTimeout(sched,24*BEAT*1000);
    };
    const buf=ac.createBuffer(1,ac.sampleRate*2,ac.sampleRate),d=buf.getChannelData(0);
    for(let i=0;i<d.length;i++)d[i]=(Math.random()*2-1)*.04;
    const ns=ac.createBufferSource();ns.buffer=buf;ns.loop=true;
    const nf=ac.createBiquadFilter();nf.type='lowpass';nf.frequency.value=700;
    const ng=ac.createGain();ng.gain.value=.01;
    ns.connect(nf);nf.connect(ng);ng.connect(master);ns.start();
    master.gain.linearRampToValueAtTime(vol,ac.currentTime+1.6);
    pad={ac,os,ns,g:master,timer:null};sched();
  }catch(e){}
}
function padPas(){const v=document.body.dataset.view;if(v==='home'||v==='dagboek'||v==='verhaal'||v==='meer')padStart();else padStop()}
addEventListener('pointerdown',()=>{padPas()},{once:true});
document.addEventListener('visibilitychange',()=>{if(document.hidden)padStop();else padPas()});
const gaOud=ga;
ga=function(s,...a){
  if(s&&s!=='home'){try{clearTimeout(vhT)}catch(e){}}
  const r=gaOud.call(this,s,...a);
  try{vakSfeer();setTimeout(padPas,80)}catch(e){}
  return r;
};
vakSfeer();

